<script>
import TitleLine from './modules/TitleLine'
import CustomerService from '@/views/portal/modules/CustomerService.vue'
export default {
  name: 'RechargeDetail',
  components: {
    TitleLine,
    CustomerService
  },
  data() {
    return {
      // currentIndex: null,
      title: this.$t('tzjl.tzjl13'),
      dataList: [
        { label: this.$t('tzjl.tzjl36'), value: '' },
        { label: this.$t('tzjl.tzjl32'), value: '' },
        { label: this.$t('tzjl.tzjl39'), value: '' },
        { label: this.$t('tzjl.tzjl40'), value: '' }
      ],
      dataList1: [
        { label: this.$t('tzjl.tzjl43'), value: '' },
        { label: this.$t('tzjl.tzjl44'), value: '' },
        { label: this.$t('tzjl.tzjl45'), value: '' },
        { label: this.$t('tzjl.tzjl46'), value: '' },
        { label: this.$t('tzjl.tzjl47'), value: '' },
        { label: this.$t('tzjl.tzjl48'), value: '' }
      ],
      showService: false,
      params: {
      },
      isCaipiao: false,
      isHash: false,
      isTouzi: false
    }
  },
  mounted() {
    // this.currentIndex = this.$route.query.currentIndex
    localStorage.getItem('tzDetail') && (this.params = JSON.parse(localStorage.getItem('tzDetail')))
    this.isCaipiao = !!((this.params.gametypename.indexOf('加拿大') >= 0))
    this.isHash = !!((this.params.gametypename.indexOf('哈希') >= 0) || (this.params.gametypename.indexOf('骰子') >= 0))
    this.isTouzi = !!((this.params.gametypename.indexOf('骰子') >= 0))
    this.dataList[0].value = this.params.btime
    this.dataList[1].value = this.params.bmons
    // this.dataList[2].value = this.params.pmons > 0 ? ('+' + this.params.pmons) : ('-' + this.params.bmons)
    this.dataList[2].value = this.params.winmons
    this.dataList[3].value = this.params.wintypename ? '已结算' : '未结算'
    this.params.blockurl = this.isHash ? this.maskString(this.params.blockurl) : this.params.blockurl
    this.params.blockhash = this.isHash ? this.maskString(this.params.blockhash) : this.params.blockhash
  },
  methods: {
    goVerify(val) {
      // window.open('https://tronscan.org/#/block/' + val)
      this.$router.push({
        path: '/verifyIndex',
        query: {
          block: val,
          blockurl: ''
        }
      })
    },
    maskString(str) { // 掩码字符串
      return str.slice(0, 4) + '****' + str.slice(-8)
    },
    goHome() { // 返回首页
      this.$router.push({ path: '/home' })
    },
    customerService() { // 联系客服
      this.showService = true
    },
    deepCopy(obj) {
      return JSON.parse(JSON.stringify(obj))
    },
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    }
  }
}
</script>
